"use client";
import React from "react";
import Reviews from "../about-us/reviews";
import Destinations from "../after-your-booking/destinations";

type Feature = {
  title: string;
  image: string;
  body: React.ReactNode;
  href: string;
};

const features: Feature[] = [
  {
    title: "Over 50,000 expertly planned adventures",
    image: "/images/advantures.jpg",
    href: "/about-us",
    body: (
      <>
        From{" "}
        <a
          href="/search?term=hiking"
          target="_blank"
          rel="noopener noreferrer"
          className="tw-font-semibold tw-text-[#854ec9] tw-no-underline"
        >
          hiking journeys
        </a>{" "}
        to{" "}
        <a
          href="/search?term=sailing"
          target="_blank"
          rel="noopener noreferrer"
          className="tw-font-semibold tw-text-[#854ec9] tw-no-underline"
        >
          sailing escapes
        </a>
        , we offer organized{" "}
        <a
          href="/search?term=adventure"
          target="_blank"
          rel="noopener noreferrer"
          className="tw-font-semibold tw-text-[#854ec9] tw-no-underline"
        >
          adventures
        </a>{" "}
        in over 160 countries, including{" "}
        <a
          href="/search?term=private"
          target="_blank"
          rel="noopener noreferrer"
          className="tw-font-semibold tw-text-[#854ec9] tw-no-underline"
        >
          private and tailored
        </a>{" "}
        trips to match your unique travel style.
      </>
    ),
  },
  {
    title: "More than 2,500 reliable suppliers",
    image: "/images/touroperator.jpg",
    href: "/suppliers",
    body: "We carefully vet all suppliers to ensure only the finest make it to our platform. Plus, we provide full supplier insolvency insurance with every booking at no extra cost, keeping your money secure.",
  },
  {
    title: "Round-the-Clock Assistance",
    image: "/images/assistant.jpg",
    href: "/contact-us",
    body: "Whether you need advice for your next trip, assistance with a booking, or support during your journey, our Travel Experts are available to help. Contact us via chat or phone anytime.",
  },
  {
    title: "Price Match Guarantee",
    image: "/images/balloon.jpg",
    href: "/why-travelshop/price-match",
    body: "With our Best Price Guarantee, you can rest assured you're getting the best deal. If you find a lower price elsewhere, we'll give you Travel Credits to apply toward your future bookings.",
  },
  {
    title: "Travel Protection Insurance",
    image: "/images/bags.jpeg",
    href: "/cancellation-policy/travel-insurance",
    body: "Travel can be unpredictable, but by adding travel insurance to your booking, you're protected against medical emergencies, trip cancellations, baggage loss, and more.",
  },
  {
    title: "Authentic Reviews",
    image: "/images/ladies.jpg",
    href: "/why-travelshop/reviews",
    body: "Your feedback is invaluable in helping us improve. Read thousands of authentic, genuine reviews from real customers, sharing their personal experiences with TravelShop Booking and the services we offer.",
  },
];

const WhyTravelShop = () => {
  return (
    <main className="tw-font-display tw-bg-white">
      {/* Hero */}
      <section className="tw-relative tw-overflow-hidden">
        <div
          className="tw-absolute tw-inset-0 tw-bg-cover tw-bg-center"
          style={{ backgroundImage: "url('/images/travellers.jpg')" }}
          aria-hidden="true"
        />
        <div
          className="tw-absolute tw-inset-0"
          style={{
            background:
              "linear-gradient(180deg, rgba(20,16,28,0.5) 0%, rgba(20,16,28,0.6) 55%, rgba(20,16,28,0.82) 100%)",
          }}
          aria-hidden="true"
        />
        <div className="tw-relative tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-24 md:tw-py-32">
          <div className="tw-max-w-[760px]">
            <span className="tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-bg-white/10 tw-border tw-border-solid tw-border-white/20 tw-px-4 tw-py-1.5 tw-text-[13px] tw-font-semibold tw-text-white tw-backdrop-blur">
              Why TravelShop Booking
            </span>
            <h1 className="tw-mt-5 tw-text-[clamp(32px,5vw,56px)] tw-font-bold tw-tracking-tight tw-leading-[1.05] tw-text-white tw-m-0">
              Advantages of Booking with TravelShop Booking
            </h1>
            <p className="tw-mt-5 tw-mb-0 tw-text-[17px] tw-leading-[1.6] tw-text-white/85 tw-max-w-[60ch]">
              Expertly planned adventures, vetted suppliers, round-the-clock
              support and a best-price promise — everything that makes
              TravelShop Booking the right choice for your next journey.
            </p>
          </div>
        </div>
      </section>

      {/* Feature cards */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-text-center tw-mb-10">
            <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              What makes TravelShop Booking the right choice?
            </h2>
          </div>
          <div className="tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 lg:tw-grid-cols-3 tw-gap-5 lg:tw-gap-6">
            {features.map((feature) => (
              <div
                key={feature.title}
                className="tw-flex tw-flex-col tw-overflow-hidden tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] hover:tw-shadow-lg tw-transition-shadow tw-duration-200"
              >
                <img
                  src={feature.image}
                  alt={feature.title}
                  loading="lazy"
                  className="tw-h-48 tw-w-full tw-object-cover"
                />
                <div className="tw-flex tw-flex-col tw-flex-1 tw-p-6">
                  <h3 className="tw-text-[18px] tw-font-bold tw-text-[#14101c] tw-m-0">
                    {feature.title}
                  </h3>
                  <p className="tw-mt-2 tw-mb-0 tw-text-[14px] tw-leading-[1.6] tw-text-[#5d556c]">
                    {feature.body}
                  </p>
                  <a
                    href={feature.href}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="tw-mt-4 tw-inline-flex tw-items-center tw-gap-2 tw-self-start tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[14px] tw-px-5 tw-py-2.5 tw-rounded-full tw-no-underline tw-transition-colors"
                  >
                    Read More <span aria-hidden="true">→</span>
                  </a>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Loyalty rewards */}
      <section className="tw-py-12 md:tw-py-16 tw-bg-[#faf9fc]">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div>
              <span className="tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#854ec9]">
                Rewards
              </span>
              <h2 className="tw-mt-2 tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                Loyalty Rewards for Future Trips
              </h2>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                Based on your TravelShop Booking booking, you have the
                opportunity to accumulate Travel Credits, which can be used to
                save money on your future adventures. The more you spend on your
                trips, the more credits you earn. For example, if your total
                spending falls within the range of $1,000 to $5,000, you will
                receive $50 in Travel Credits. Keep booking and exploring to
                maximize your rewards!
              </p>
              <a
                href="/after-your-booking/invite"
                target="_blank"
                rel="noopener noreferrer"
                className="tw-mt-6 tw-inline-flex tw-items-center tw-gap-2 tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[15px] tw-px-6 tw-py-3.5 tw-rounded-full tw-no-underline tw-transition-colors"
              >
                Read how to earn credits <span aria-hidden="true">→</span>
              </a>
            </div>
            <div>
              <img
                src="/images/travelers.avif"
                alt="Travelers earning rewards"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
          </div>
        </div>
      </section>

      {/* Independent suppliers */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div className="tw-order-2 lg:tw-order-1">
              <img
                src="/images/guide.png"
                alt="Local tour guide"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
            <div className="tw-order-1 lg:tw-order-2">
              <span className="tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#854ec9]">
                Sustainability
              </span>
              <h2 className="tw-mt-2 tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                We back independent suppliers!
              </h2>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                TravelShop Booking partners with a variety of tour suppliers,
                including smaller, locally based ones, to provide unique and
                high-quality travel experiences that positively impact local
                communities. We are also dedicated to ensuring that all
                suppliers follow sustainable practices by 2030. On each tour
                detail page, you can explore the sustainability efforts already
                in place.
              </p>
              <a
                href="/why-travelshop/sustainability"
                target="_blank"
                rel="noopener noreferrer"
                className="tw-mt-6 tw-inline-flex tw-items-center tw-gap-2 tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[15px] tw-px-6 tw-py-3.5 tw-rounded-full tw-no-underline tw-transition-colors"
              >
                Explore our sustainability commitments{" "}
                <span aria-hidden="true">→</span>
              </a>
            </div>
          </div>
        </div>
      </section>

      {/* Trustpilot reviews (shared) */}
      <Reviews />

      <Destinations />
    </main>
  );
};

export default WhyTravelShop;
